            <div class="form-row calendar-holiday-attrs"><div><div class="label">Relative trigger ${u(o["Use relative trigger"]||"")}</div></div><div class="calendar-holiday-attrs__list"><label class="calendar-holiday-attr"><input id="calHolidayUseRelative" type="checkbox" />Use relative trigger</label></div></div>
